# Capability substitution and failover: Signature Second Road
primary = "first-road"; substitutes = "second-road".split(";")
FAIL = True
def call(cap):
    if cap == primary and FAIL:
        raise RuntimeError("primary down: first road impassable")
    return "result-from-" + cap
for cap in [primary] + substitutes:
    try:
        print(call(cap)); break
    except RuntimeError as e:
        print("failover:", e)
print("OK - substitution kept the work going")

